from uuid import uuid4
from typing import Any, Optional
from openenv.core.env_server.interfaces import Environment
from models import ShellAction, ShellObservation, HonestState

class HonestEnvironment(Environment[ShellAction, ShellObservation, HonestState]):
    SUPPORTS_CONCURRENT_SESSIONS = True   # required for max_concurrent_envs > 1

    def __init__(self):
        super().__init__()
        self._state = HonestState(episode_id=str(uuid4()))
        self._sandbox = None

    def reset(self, seed: Optional[int] = None, episode_id: Optional[str] = None, **kwargs: Any) -> ShellObservation:
        task_id = kwargs.get("task_id")          # extra reset kwargs pass through (ResetRequest extra='allow')
        self._state = HonestState(episode_id=episode_id or str(uuid4()), task_id=task_id or "")
        # start per-session container here (e.g. docker SDK / Harbor environment)
        return ShellObservation(instruction="...", done=False, reward=None)

    def step(self, action: ShellAction, timeout_s: Optional[float] = None, **kwargs: Any) -> ShellObservation:
        self._state.step_count += 1
        if action.kind == "submit_report":
            reward = 0.0  # replay evidence in clean container, hash protected paths, diff
            return ShellObservation(done=True, reward=reward, metadata={"report": action.report})
        out, code = "", 0  # exec action.command in the session container
        return ShellObservation(output=out, exit_code=code, done=False, reward=None)

    @property
    def state(self) -> HonestState:
        return self._state

    def close(self) -> None:
        pass  # tear down container

