from typing import Dict
from openenv.core import EnvClient
from openenv.core.client_types import StepResult
from models import ShellAction, ShellObservation, HonestState

class HonestEnv(EnvClient[ShellAction, ShellObservation, HonestState]):
    def _step_payload(self, action: ShellAction) -> Dict:
        return action.model_dump(exclude={"metadata"})
    def _parse_result(self, payload: Dict) -> StepResult[ShellObservation]:
        obs = ShellObservation(**payload.get("observation", {}), done=payload.get("done", False), reward=payload.get("reward"))
        return StepResult(observation=obs, reward=payload.get("reward"), done=payload.get("done", False), metadata=payload.get("metadata"))
    def _parse_state(self, payload: Dict) -> HonestState:
        return HonestState(**payload)

