# Environment with env-owned reward (docs/source/grpo_trainer.md)
class IncrementEnv:
    def reset(self, target, **kwargs) -> None:
        self.counter = 0; self.target = target
    def get_reward(self) -> float:
        return float(self.counter == self.target)
    def increment(self, step: int) -> int:
        """Increment the internal counter.

        Args:
            step: Value to add to the counter.

        Returns:
            The updated counter value.
        """
        self.counter += step; return self.counter

