from uuid import uuid4
from typing import Any, Optional
from openenv.core.env_server.interfaces import Environment

class HonestEnvironment(Environment[ShellAction, ShellObservation, HonestState]):
    SUPPORTS_CONCURRENT_SESSIONS = True   # else max_concurrent_envs>1 raises ConcurrencyConfigurationError

    def __init__(self):
        super().__init__()                # (transform=None, rubric=None)
        self._state = HonestState(episode_id=str(uuid4()))

    def reset(self, seed: Optional[int] = None, episode_id: Optional[str] = None, **kwargs: Any) -> ShellObservation:
        # WS reset forwards all client kwargs because of **kwargs (filtered by signature otherwise)
        self._state = HonestState(episode_id=episode_id or str(uuid4()), task_id=kwargs.get("task_id", ""))
        return ShellObservation(instruction="...")

    def step(self, action: ShellAction, timeout_s: Optional[float] = None, **kwargs: Any) -> ShellObservation:
        # over WS, timeout_s is always None here -> enforce action.timeout_s yourself
        self._state.step_count += 1
        if action.kind == "submit_report":
            return ShellObservation(done=True, reward=0.0, metadata={"report": action.report})
        return ShellObservation(output="", exit_code=0)

    @property
    def state(self) -> HonestState:
        return self._state

    def close(self) -> None: ...

